window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-66815680610a2479"]={"versions": [{"id": "FIG-66815680610a2479", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Compute CRC“ innerhalb der E2E-Transformator-/Forward-Funktion <code>E2E_P22Forward()</code> (AUTOSAR End-to-End Profile 22, Classic / Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Scope:</strong> <code>E2E_P22Forward()</code>\n</li><li><strong>Konfigurationsstrukturelemente:</strong> <code>Config-&gt;Offset</code>, <code>Config-&gt;CRCOffset</code>, <code>Config-&gt;DataIDList</code>\n</li><li><strong>Lokale / Zustandsvariablen:</strong> <code>Offset</code>, <code>ComputedCRC</code> (uint8), <code>Data</code> (Array / Byte-Puffer), <code>Length</code>, <code>ForwardStatus</code> (vom Typ/Wert <code>E2E_P_ERROR</code>), <code>DataID</code>, <code>Counter</code>\n</li><li><strong>Externe Bibliotheksfunktion:</strong> <code>Crc_CalculateCRC8H2F(Crc_DataPtr, Crc_Length, Crc_StartValue8, Crc_IsFirstCall)</code> aus der AUTOSAR CRC-Bibliothek\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Berechnung von <code>Offset = Config-&gt;Offset / 8</code>.\n</li><li><strong>Prüfung CRC-Offset (<code>Config-&gt;CRCOffset &gt; 0</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Pfad <code>[TRUE]</code>:</strong> \n<ul class=\"fig-list\"><li>Erste Teilberechnung: <code>uint8 ComputedCRC = Crc_CalculateCRC8H2F(Crc_DataPtr: &amp;Data[0], Crc_Length: Offset, Crc_StartValue8: 0xFF, Crc_IsFirstCall: TRUE)</code>.\n</li><li>Zweite Teilberechnung (unter Auslassung des CRC-Felds): <code>ComputedCRC = Crc_CalculateCRC8H2F(Crc_DataPtr: &amp;Data[Offset+1], Crc_Length: Length-Offset-1, Crc_StartValue8: ComputedCRC, Crc_IsFirstCall: FALSE)</code>.\n</li></ul>\n</li><li><strong>Pfad <code>[FALSE]</code>:</strong>\n<ul class=\"fig-list\"><li>Direkte Berechnung über die Nutzdaten ab Byte 1: <code>uint8 ComputedCRC = Crc_CalculateCRC8H2F(Crc_DataPtr: &amp;Data[1], Crc_Length: Length-1, Crc_StartValue8: 0xFF, Crc_IsFirstCall: TRUE)</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Zusammenführung und Fehlerstatusprüfung (<code>if ForwardStatus == E2E_P_ERROR</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Pfad <code>[TRUE]</code>:</strong> Invalidation bzw. Fehlerfall-Identifikator durch <code>DataID = Config-&gt;DataIDList[Counter] + 1</code>.\n</li><li><strong>Pfad <code>[FALSE]</code>:</strong> Regulärer Identifikator durch <code>DataID = Config-&gt;DataIDList[Counter]</code>.\n</li></ul>\n</li><li><strong>CRC-Abschluss mit DataID:</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>ComputedCRC = Crc_CalculateCRC8H2F(DataID, Crc_Length: 1, Crc_StartValue8: ComputedCRC, Crc_IsFirstCall: FALSE)</code>.\n</li></ul>\n</li><li><strong>Aktivitätsende:</strong> Erreichen des finalen Knotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Spezifikationsanforderung:</strong> Referenziert PRS_E2E_00638.\n</li><li><strong>Implementierungsdetails:</strong>\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code> ist in Bits spezifiziert und muss vor der Adressierung in Byte-Offsets konvertiert werden (<code>/ 8</code>).\n</li><li>Der Algorithmus nutzt CRC8H2F (Polynom 0x2F / Koopman 0x97 / HD=4). Startwert für den Initialaufruf ist stets <code>0xFF</code>.\n</li><li>Die CRC-Berechnung spart die Position der Prüfsumme selbst aus (Offset-Splitting bei Offset &gt; 0 bzw. Start bei Index 1 bei Offset == 0).\n</li><li>Zur Fehleranzeige gegenüber nachgelagerten Empfängern im Forwarding-Fehlerfall (<code>ForwardStatus == E2E_P_ERROR</code>) wird die DataID gezielt verfälscht (+1), sodass beim Empfänger ein CRC-Fehler erkannt wird.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8704031644aa8a49", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Compute CRC“ innerhalb der E2E-Transformator-/Forward-Funktion <code>E2E_P22Forward()</code> (AUTOSAR End-to-End Profile 22, Classic / Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktion / Scope:</strong> <code>E2E_P22Forward()</code>\n</li><li><strong>Konfigurationsstrukturelemente:</strong> <code>Config-&gt;Offset</code>, <code>Config-&gt;CRCOffset</code>, <code>Config-&gt;DataIDList</code>\n</li><li><strong>Lokale / Zustandsvariablen:</strong> <code>Offset</code>, <code>ComputedCRC</code> (uint8), <code>Data</code> (Array / Byte-Puffer), <code>Length</code>, <code>ForwardStatus</code> (vom Typ/Wert <code>E2E_P_ERROR</code>), <code>DataID</code>, <code>Counter</code>\n</li><li><strong>Externe Bibliotheksfunktion:</strong> <code>Crc_CalculateCRC8H2F(Crc_DataPtr, Crc_Length, Crc_StartValue8, Crc_IsFirstCall)</code> aus der AUTOSAR CRC-Bibliothek\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Berechnung von <code>Offset = Config-&gt;Offset / 8</code>.\n</li><li><strong>Prüfung CRC-Offset (<code>Config-&gt;CRCOffset &gt; 0</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Pfad <code>[TRUE]</code>:</strong> \n<ul class=\"fig-list\"><li>Erste Teilberechnung: <code>uint8 ComputedCRC = Crc_CalculateCRC8H2F(Crc_DataPtr: &amp;Data[0], Crc_Length: Offset, Crc_StartValue8: 0xFF, Crc_IsFirstCall: TRUE)</code>.\n</li><li>Zweite Teilberechnung (unter Auslassung des CRC-Felds): <code>ComputedCRC = Crc_CalculateCRC8H2F(Crc_DataPtr: &amp;Data[Offset+1], Crc_Length: Length-Offset-1, Crc_StartValue8: ComputedCRC, Crc_IsFirstCall: FALSE)</code>.\n</li></ul>\n</li><li><strong>Pfad <code>[FALSE]</code>:</strong>\n<ul class=\"fig-list\"><li>Direkte Berechnung über die Nutzdaten ab Byte 1: <code>uint8 ComputedCRC = Crc_CalculateCRC8H2F(Crc_DataPtr: &amp;Data[1], Crc_Length: Length-1, Crc_StartValue8: 0xFF, Crc_IsFirstCall: TRUE)</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Zusammenführung und Fehlerstatusprüfung (<code>if ForwardStatus == E2E_P_ERROR</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Pfad <code>[TRUE]</code>:</strong> Invalidation bzw. Fehlerfall-Identifikator durch <code>DataID = Config-&gt;DataIDList[Counter] + 1</code>.\n</li><li><strong>Pfad <code>[FALSE]</code>:</strong> Regulärer Identifikator durch <code>DataID = Config-&gt;DataIDList[Counter]</code>.\n</li></ul>\n</li><li><strong>CRC-Abschluss mit DataID:</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>ComputedCRC = Crc_CalculateCRC8H2F(DataID, Crc_Length: 1, Crc_StartValue8: ComputedCRC, Crc_IsFirstCall: FALSE)</code>.\n</li></ul>\n</li><li><strong>Aktivitätsende:</strong> Erreichen des finalen Knotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Spezifikationsanforderung:</strong> Referenziert PRS_E2E_00638.\n</li><li><strong>Implementierungsdetails:</strong>\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code> ist in Bits spezifiziert und muss vor der Adressierung in Byte-Offsets konvertiert werden (<code>/ 8</code>).\n</li><li>Der Algorithmus nutzt CRC8H2F (Polynom 0x2F / Koopman 0x97 / HD=4). Startwert für den Initialaufruf ist stets <code>0xFF</code>.\n</li><li>Die CRC-Berechnung spart die Position der Prüfsumme selbst aus (Offset-Splitting bei Offset &gt; 0 bzw. Start bei Index 1 bei Offset == 0).\n</li><li>Zur Fehleranzeige gegenüber nachgelagerten Empfängern im Forwarding-Fehlerfall (<code>ForwardStatus == E2E_P_ERROR</code>) wird die DataID gezielt verfälscht (+1), sodass beim Empfänger ein CRC-Fehler erkannt wird.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-66815680610a2479", "to": "FIG-8704031644aa8a49", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
